from solution import gcd


def test_issue_example_12_17():
    """Check example assert gcd(12, 17) == 1."""
    assert gcd(12, 17) == 1  # 12=2*2*3, 17 prime, common=1


def test_issue_common_divisor_12_18():
    """Find gcd of two positive integers with common factors."""
    assert gcd(12, 18) == 6  # 12=2*2*3, 18=2*3*3, common 2*3=6


def test_issue_one_divides_other_5_20():
    """Find gcd of two positive integers where one divides the other."""
    assert gcd(5, 20) == 5  # 5=5, 20=2*2*5, common=5


def test_issue_equal_inputs_7_7():
    """Find gcd of two positive integers that are equal."""
    assert gcd(7, 7) == 7  # 7=7, 7=7, common=7


def test_issue_one_is_one_1_9():
    """Find gcd of two positive integers when one input is 1."""
    assert gcd(1, 9) == 1  # divisors of 1 are {1}, so common=1


def test_issue_both_one_1_1():
    """Find gcd of two positive integers both equal to 1."""
    assert gcd(1, 1) == 1  # divisors of 1 are {1}, so common=1


def test_issue_distinct_primes_13_19():
    """Find gcd of two positive integers that are distinct primes."""
    assert gcd(13, 19) == 1  # 13 prime, 19 prime, common=1


def test_issue_larger_pair_48_180():
    """Find gcd of two positive integers with larger values."""
    assert gcd(48, 180) == 12  # 48=2*2*2*2*3, 180=2*2*3*3*5, common 2*2*3=12


def test_issue_order_swapped_18_12():
    """Find gcd of two positive integers independent of argument order."""
    assert gcd(18, 12) == 6  # 18=2*3*3, 12=2*2*3, common 2*3=6


def test_issue_common_factor_75_100():
    """Find gcd of two positive integers sharing a larger factor."""
    assert gcd(75, 100) == 25  # 75=3*5*5, 100=2*2*5*5, common 5*5=25


def test_contract_callable_two_args():
    """Implement gcd(x, y) in solution.py as a callable."""
    assert callable(gcd)


def test_contract_returns_int():
    """Implement gcd(x, y) in solution.py returning a positive integer."""
    assert isinstance(gcd(12, 18), int)  # 12=2*2*3, 18=2*3*3, gcd 2*3=6 is int
